{"file_path":"safety_evals/metrics.py","content":""""AI alignment evaluation: monitor flag statistics over model transcripts."""


def monitor_flag_rate(events):
    """The share of transcripts whose ``flagged`` value is True."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event["flagged"] is True)
    return hits / len(events)


def pooled_flag_rate(groups):
    """The pooled flag rate across all transcripts in all groups."""
    events = [event for transcripts in groups.values() for event in transcripts]
    return monitor_flag_rate(events)


def flags_in_window(daily_counts, days):
    """Sum the last ``days`` entries of daily counts (oldest first)."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def flag_rate_by_group(groups):
    """Map each group name to its flag rate (None for an empty group)."""
    return {
        name: monitor_flag_rate(events) if events else None
        for name, events in sorted(groups.items())
    }


def longest_flag_streak(daily_counts):
    """Return the longest run of consecutive entries greater than zero."""
    best = cur = 0
    for count in daily_counts:
        if count > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best
